cd app/chrome-extension/webmcp && python3 - <<'EOF'
p='webmcp-manager.ts'
s=open(p).read()
lines=s.split('\n')
def find(prefix,start=0):
    for i in range(start,len(lines)):
        if lines[i].startswith(prefix): return i
    raise Exception(prefix)
# 1) remove lines 11..106 (worldbook config through storage listener), keep "// Debounce timeout"
a=find('// Worldbook API configuration'); b=find('// Debounce timeout')
del lines[a:b]
# 2) remove API types
a=find('// API response types'); b=find('// Store currently registered site tools')
del lines[a:b]
# 3) remove convertApiConfig + fetchSiteConfigFromAPI, rewrite getSiteConfig
a=find('/**', find('function mergeSiteConfigs')); 
# find the doc comment for convertApiConfig: first '/**' after mergeSiteConfigs
b=find('/**', find('async function getSiteConfig')-3)
# b should be the getSiteConfig doc comment
end=find('}', find('async function getSiteConfig'))
lines[a:end+1]='''/**
 * Get site config from local built-in and recorded configs
 */
async function getSiteConfig(url: string): Promise<SiteConfig | null> {
  const recordedConfig = await getLocalRecordedSiteConfig(url);
  const localConfig = matchSiteConfig(url);
  if (localConfig) {
    console.log(`[WebMCP] Using local config: ${localConfig.siteName}`);
  }
  return mergeSiteConfigs(localConfig, recordedConfig);
}'''.split('\n')
# 4) getConfiguredSites
a=find('  // Check if Worldbook WebMCP is enabled'); b=find('  // Return local config as fallback')
del lines[a:b+1]
s='\n'.join(lines).replace(' * Get all configured sites list (from API)',' * Get all configured sites list (built-in and recorded)')
open(p,'w').write(s)
EOF
git diff --stat; sed -n 1,20p webmcp-manager.ts; grep -n "getSiteConfig\|getConfiguredSites" -A12 webmcp-manager.ts | head -60

